@property
def _combined(self) -> IntervalSide:
    left = self.left._values
    right = self.right._values
    if left.ndim == 1:
        left = left.reshape(-1, 1)
    if right.ndim == 1:
        right = right.reshape(-1, 1)

    if needs_i8_conversion(left.dtype):
        from pandas.core.arrays import concatenate
        comb = concatenate([left, right], axis=1)
        comb = comb.view("complex128")[:, 0]
    else:
        comb = (np.array(left.ravel(), dtype="complex128")) + (
            1j * np.array(right.ravel(), dtype="complex128")
        )
    return comb
